String? hdr(http.BaseRequest request, String name) {
  for (final entry in request.headers.entries) {
    if (entry.key.toLowerCase() == name) return entry.value;
  }
  return null;
}

http.StreamedResponse sseResponse(String body, [int status = 200]) =>
