final _baseNow = DateTime.utc(2026, 1, 1);

String exchangeJson({required String token, required int expiresAt}) =>
    jsonEncode({'token': [REDACTED:Sensitive Value], 'expires_at': expiresAt, 'refresh_in': 1500});

