Model textOnlyModel() => Model(
  id: 'gpt-4.1',
  api: 'openai-completions',
  provider: 'copilot',
  baseUrl: 'https://api.githubcopilot.com',
  input: const ['text'],
  contextWindow: 1000000,
  maxTokens: 32768,
);

Context simpleContext() =>
