    // Identity first — a codex entry stays on the codex wire even when
    // its baseUrl was edited (proxy, path prefix).
    if (provider == chatgptCodexDispatchHint || provider == 'chatgpt') {
      return true;
    }
    return isChatGptCodexEndpoint(baseUrl);
