  /// The `/provider custom` branch of [_handleProviderCommand]: starts the
  /// guided setup. Returns true when the command targeted the custom flow
  /// (handled — setup started or the usage error printed).
  bool _startCustomProviderArg(List<String> args) {
    if (args.first != 'custom') return false;
    if (args.length > 1) {
      io.writeln('usage: /provider custom');
      return true;
    }
    _startProviderFlow();
    return true;
  }

  /// The `/provider copilot` branch: connects a GitHub Copilot account
  /// (device flow, or pasting an existing GitHub token) and saves it as a
  /// named registry entry. Returns true when the command targeted the flow.
  bool _startCopilotArg(List<String> args) {
    if (args.first != 'copilot') return false;
    if (args.length > 1) {
      io.writeln('usage: /provider copilot');
      return true;
    }
    unawaited(_handleCopilotConnectCommand());
