    Future<String> Function({
      String? clientId,
      void Function(String)? onStatus,
    })?
    copilotDeviceFlowFn,
    Future<String> Function(String githubToken)? copilotUserFn,
    Future<CodeMieSsoCredentials?> Function(
      String codeMieUrl,
