String sseChunk(Map<String, dynamic> json) => 'data: ${jsonEncode(json)}\n\n';

const _doneChunk = 'data: [DONE]\n\n';

String chatSse({String text = 'Hel lo'}) =>
    sseChunk({
      'id': 'chatcmpl-1',
      'model_picker_enabled': true,
      'choices': [
        {
