          apiKey: [REDACTED:Sensitive Value],
          cancelToken: cancelToken,
          sessionId: effectiveSessionId,
          cacheRetention: effectiveRetention,
        ),
      ),
      'anthropic' => streamAnthropic(
        model,
        context,
        AnthropicOptions(
          apiKey: [REDACTED:Sensitive Value],
          cancelToken: cancelToken,
          cacheRetention: effectiveRetention,
        ),
      ),
      'google' => streamGoogle(
        model,
        context,
        GoogleOptions(apiKey: [REDACTED:Sensitive Value], cancelToken: cancelToken),
      ),
      'dial' => streamDial(
        model,
        context,
        DialOptions(
          apiKey: [REDACTED:Sensitive Value],
          apiVersion: _dialApiVersion,
          cancelToken: cancelToken,
          sessionId: effectiveSessionId,
          cacheRetention: effectiveRetention,
          cacheMarkersSupported: _dialCacheMarkersSupported,
        ),
      ),
      'copilot' => streamCopilot(
        model,
        context,
        CopilotOptions(
          githubToken: _apiKey,
          cancelToken: cancelToken,
          sessionId: effectiveSessionId,
          cacheRetention: effectiveRetention,
        ),
      ),
      'chatgpt-codex' => streamChatGptCodex(
