```dart
/// The host-installed `copilot/<fa-version> (<os>)` user-agent prefix for
/// PAT-mode requests (the official Copilot CLI's shape). The CLI/app
/// installs the real version+OS at startup via
/// [installCopilotCliIdentity] (dart:io lives in bin/); the default keeps
/// provider requests working (and tests deterministic) without it.
String _copilotCliVersion = 'fa';
String _copilotCliOs = 'unknown';

/// Installs the host's version + OS for the PAT-mode user-agent.
void installCopilotCliIdentity({required String version, required String os}) {
  _copilotCliVersion = version;
  _copilotCliOs = os;
}

String get _copilotCliUserAgent => 'copilot/$_copilotCliVersion ($_copilotCliOs) term/unknown';
```

