/// for exchanged OAuth tokens).
const copilotDeveloperCliIntegrationId = 'copilot-developer-cli';

/// The host-installed version for the PAT-mode user-agent
/// (`copilot/<version> (<os>) term/unknown`). bin/fah.dart installs the
/// real package version at startup via [installCopilotCliIdentity]; the
/// default keeps provider requests working without a host.
String _copilotCliVersion = 'fa';

/// The host-installed OS for the PAT-mode user-agent (see
