String _copilotCliOs = 'unknown';

/// Installs the host's version + OS for the PAT-mode user-agent. Hosts
/// call this once at startup (dart:io owns `Platform.operatingSystem`,
/// and this library stays pure Dart).
void installCopilotCliIdentity({required String version, required String os}) {
  _copilotCliVersion = version;
  _copilotCliOs = os;
