      expect(runner.calls.single.$1, 'clip');
      expect(runner.calls.single.$3, 'gho_TOKEN');
    });

    test('every path failing becomes a named unavailable', () async {
      final runner = _RecordingRunner(1);

      final result = await writeClipboardText(
        'tok',
        runner: runner.call,
        platform: 'linux',
